/** The about text for a locale, falling back to English. */
export function aboutTextFor(id?: string, locale: Locale = 'en'): AboutText | undefined {
  if (!id) return undefined;
  return (
    (locale === 'de' && ABOUT_TEXT_DE[id]) ||
    (locale === 'pt' && ABOUT_TEXT_PT[id]) ||
    (locale === 'it' && ABOUT_TEXT_IT[id]) ||
    (locale === 'fr' && ABOUT_TEXT_FR[id]) ||
    (locale === 'es' && ABOUT_TEXT_ES[id]) ||
    ABOUT_TEXT[id]
  );
}
